    coords: [16.840, 46.845],
    name: { de: "Bekleidungswerk Zalaegerszeg", hu: "Zalaegerszegi ruhagyár", ro: "Fabrica de Confecții Zalaegerszeg", en: "Zalaegerszeg Clothing Factory" },
